// WF-04 · Planificación de la contención.
//
// Este nodo NO ejecuta nada: decide qué acciones corresponden y construye,
// para cada una, su reversión exacta y su caducidad. La reversión se define
// aquí, cuando aún se tiene todo el contexto — no después, cuando alguien
// intente deshacer un bloqueo de hace tres semanas.

// @blinksec-inject: lib/containment.js

const alerta = $input.first().json;

const plan = planContainment(alerta, alerta.triage, {
  agentId: alerta.agent_id,
  accountId: $env.CLOUDFLARE_ACCOUNT_ID,
  platforms: {
    ip: 'cloudflare',
    // Se activan conforme se integran las plataformas correspondientes.
    // endpoint: 'crowdstrike',
    // identity: 'entra_id',
  },
});

if (plan.actions.length === 0) {
  return [{ json: { ...alerta, plan, sinAcciones: true } }];
}

return [{ json: { ...alerta, plan, sinAcciones: false } }];

// WF-04 · Registro de contención omitida.
//
// Que el sistema decida NO contener es información operativa de primer orden:
// si esta rama se dispara con frecuencia, o el motor de triaje está mal
// calibrado o el inventario de activos está incompleto. Un 'no hice nada'
// silencioso es indistinguible de un flujo roto.

const a = $input.first().json;

return [
  {
    json: {
      evento: 'contencion_omitida',
      alert_id: a.alert_id,
      motivos: a.plan?.skipped ?? [],
      veredicto: a.triage?.verdict,
      puntuacion: a.triage?.score,
      timestamp: new Date().toISOString(),
    },
  },
];
